//! [pso2_vita_offline] Starter kit (T104): a ★1 weapon of the main class (equipped on palette 1), a few
//! consumables and meseta, for new characters and, once, for existing characters with no weapon at all.
//! Data: `data/starter_kit.json` (`PSO2_STARTER_FILE` overrides), generated by `tools/gen_starter_kit.py`.
use crate::sql::CharData;
use pso2packetlib::protocol::{
    items::{Item, ItemId, ItemType, WeaponItem, ConsumableItem},
    models::character::Class,
    palette::WeaponPalette,
};
use serde::Deserialize;
use std::{collections::HashMap, sync::OnceLock};

#[derive(Deserialize, Default)]
#[serde(default)]
pub struct Kit {
    items: Vec<KitItem>,
    stack: u16,
    meseta: u64,
    weapons: HashMap<String, KitWeapon>,
}

#[derive(Deserialize, Default)]
#[serde(default)]
struct KitItem {
    spec: String,
    amount: u16,
}

#[derive(Deserialize, Default)]
#[serde(default)]
struct KitWeapon {
    id: u16,
    subid: u16,
}

fn kit() -> &'static Kit {
    static KIT: OnceLock<Kit> = OnceLock::new();
    KIT.get_or_init(|| {
        let path = std::env::var_os("PSO2_STARTER_FILE").unwrap_or_else(|| "data/starter_kit.json".into());
        match std::fs::read_to_string(&path).map(|s| serde_json::from_str::<Kit>(&s)) {
            Ok(Ok(k)) => {
                log::info!("[pso2-starter] {} classes, meseta {}", k.weapons.len(), k.meseta);
                k
            }
            e => {
                log::warn!("[pso2-starter] no kit ({:?}): {}", path, e.map(|_| ()).unwrap_err_or_none());
                Kit::default()
            }
        }
    })
}

trait ErrText {
    fn unwrap_err_or_none(self) -> String;
}
impl<E: std::fmt::Debug> ErrText for Result<(), E> {
    fn unwrap_err_or_none(self) -> String {
        format!("{:?}", self)
    }
}

/// Give the kit. `uuid` is the user's last_uuid. Returns false when the kit is empty.
pub fn grant(char: &mut CharData, uuid: &mut u64) -> bool {
    let kit = kit();
    if kit.weapons.is_empty() && kit.items.is_empty() && kit.meseta == 0 {
        return false;
    }
    let class = format!("{:?}", char.character.classes.main_class);
    if let Some(w) = kit.weapons.get(&class) {
        let item = Item {
            uuid: 0,
            id: ItemId { item_type: 1, id: w.id, unk3: 0, subid: w.subid },
            data: ItemType::Weapon(WeaponItem::default()),
        };
        if let Some(added) = char.inventory.add_bought(&item, 1, 1, uuid).first() {
            char.palette.set_palette_data(0, WeaponPalette { uuid: added.uuid, ..Default::default() });
        }
    }
    for k in &kit.items {
        let n: Vec<u16> = k.spec.split(':').filter_map(|s| s.parse().ok()).collect();
        let [t, id, sub] = n[..] else { continue };
        let item = Item {
            uuid: 0,
            id: ItemId { item_type: t, id, unk3: 0, subid: sub },
            data: ItemType::Consumable(ConsumableItem { amount: k.amount, ..Default::default() }),
        };
        char.inventory.add_bought(&item, k.amount, kit.stack.max(1), uuid);
    }
    if kit.meseta > 0 {
        let _ = char.inventory.add_meseta(kit.meseta);
    }
    char.starter_given = true;
    true
}

/// True when the character has no weapon in the bag and nothing on palette 1 (a character made before T104).
pub fn needs(char: &CharData) -> bool {
    !char.starter_given
        && !char.inventory.bag_items().iter().any(|i| i.id.item_type == 1)
        && !char.palette.has_weapon()
}

#[allow(dead_code)]
fn _unused(_: Class) {}
